#!/usr/bin/env bash
# make_repo.sh — self-contained. Unpacks full GhoSty Commercial project.
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$ROOT"
echo "==> Unpacking GhoSty Commercial project..."

PAYLOAD_B64=$(cat << 'B64EOF'

B64EOF
)

echo "$PAYLOAD_B64" | base64 -d > /tmp/ghosty-payload.tar.gz
tar -xzf /tmp/ghosty-payload.tar.gz -C "$ROOT"
rm -f /tmp/ghosty-payload.tar.gz

# Ensure dirs
mkdir -p bot selfbot core/letters .github/workflows
touch bot/__init__.py selfbot/__init__.py core/__init__.py

if [ ! -f core/letters/README.txt ]; then
  cat > core/letters/README.txt << 'EOF'
Copy original Ghosty core/letters/*.png templates here (folders 0-4).
Without them HuntBot captcha solving fails.
EOF
fi

if [ ! -f .gitignore ]; then
  cat > .gitignore << 'EOF'
.env
*.token
tokens.txt
__pycache__/
*.py[cod]
venv/
.venv/
env/
.idea/
.vscode/
.DS_Store
*.log
ghostyhbworkers.json
ghostyworkerquests.json
EOF
fi

echo "==> Done. Project layout:"
find . -type f -not -path './.git/*' | sort
echo ""
echo "Remember to copy captcha letter PNGs into core/letters/"
